BEGIN;

SET LOCAL standard_conforming_strings = on;

INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷85·晋少帝本纪·出帝降表后半", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ecde5726bec9b8402d248a26c53a28ede8152696/content/books/zizhi-tongjian/vol-285/year-0946/part-07/sources/library/jiuwudaishi-085-shi-surrender-memorial/source.txt", "note": "《旧五代史》卷85·晋少帝本纪·出帝降表后半，段落 jiu-wudaishi-205deb4a7860-p002050；已回查卷题、传主与上下文，纸本及异文待核。", "id": "f1380638-b9d3-5f98-8742-46e4cb1b1cf3"}, {"title": "旧五代史·卷89·桑维翰传·国亡遇害前后", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ecde5726bec9b8402d248a26c53a28ede8152696/content/books/zizhi-tongjian/vol-285/year-0946/part-07/sources/library/jiuwudaishi-089-sang-captive/source.txt", "note": "《旧五代史》卷89·桑维翰传·国亡遇害前后，段落 jiu-wudaishi-205deb4a7860-p002135；已回查卷题、传主与上下文，纸本及异文待核。", "id": "7b9235ce-f2ce-5c4c-85f7-c6034475b192"}, {"title": "资治通鉴·卷285·开运三年·十二月降帝及迎契丹", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ecde5726bec9b8402d248a26c53a28ede8152696/content/books/zizhi-tongjian/vol-285/year-0946/part-07/sources/library/tongjian-285-946-captive-emperor/source.txt", "note": "《资治通鉴》卷285·开运三年·十二月降帝及迎契丹，段落 zizhi-tongjian-a63549944a71-p003392；已回查卷题、传主与上下文，纸本及异文待核。", "id": "e9102fd2-3993-5c29-aef7-615eec5d17d7"}, {"title": "新五代史·卷17·晋家人传·出帝降表", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/ecde5726bec9b8402d248a26c53a28ede8152696/content/books/zizhi-tongjian/vol-285/year-0946/part-07/sources/library/xinwudaishi-017-shi-surrender-memorial/source.txt", "note": "《新五代史》卷17·晋家人传·出帝降表，段落 xin-wudaishi-b08f244b9241-p000563；已回查卷题、传主与上下文，纸本及异文待核。", "id": "6edb34af-3a1b-54c0-ab3f-9207621e36b6"}, {"title": "资治通鉴·卷285·开运三年·十二月南进及京城前后", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c7d707f140aeeb6d7f8cb666674b4e39a39263b6/content/books/zizhi-tongjian/vol-285/year-0946/part-06/sources/library/tongjian-285-946-surrender-capital/source.txt", "note": "《资治通鉴》卷285·开运三年·十二月南进及京城前后，段落 zizhi-tongjian-a63549944a71-p003391；已回查正文卷号、传主与上下文，纸本及异文待核。", "id": "3681fa21-0224-54a3-9d77-213b1dbabd97"}, {"title": "旧五代史·卷85·晋少帝本纪·开运三年十二月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c7d707f140aeeb6d7f8cb666674b4e39a39263b6/content/books/zizhi-tongjian/vol-285/year-0946/part-06/sources/library/jiuwudaishi-085-946-december/source.txt", "note": "《旧五代史》卷85·晋少帝本纪·开运三年十二月，段落 jiu-wudaishi-205deb4a7860-p002047；已回查正文卷号、传主与上下文，纸本及异文待核。", "id": "8477d7d0-42dd-56cb-92cf-7752d47cdc14"}, {"title": "新五代史·卷9·晋本纪·开运三年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/c7d707f140aeeb6d7f8cb666674b4e39a39263b6/content/books/zizhi-tongjian/vol-285/year-0946/part-06/sources/library/xinwudaishi-009-946/source.txt", "note": "《新五代史》卷9·晋本纪·开运三年，段落 xin-wudaishi-b08f244b9241-p000337；已回查正文卷号、传主与上下文，纸本及异文待核。", "id": "90a0bab8-962e-598e-a354-e5da6a3522fe"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "皇甫遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：皇甫遇，原严卫步军都指挥使、接侍卫步军者。", "biography": null, "status": "draft", "id": "0aa52fa6-cacc-5960-8646-9ab3a0393623"}, {"name": "耶律德光", "aliases": ["德光"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：耶律德光，守西楼、受号者。", "biography": null, "status": "draft", "id": "64c415ac-57fe-571c-8c6f-3ed68fb726da"}, {"name": "张彦泽", "aliases": ["張彥澤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，938年任镇国军节度使，在华州截击并杀死东行的凤翔叛军。生卒年本段未载。", "biography": null, "status": "draft", "id": "194d0f9a-3b17-5635-9741-dffc983ee32e"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "李崧", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：李崧。", "biography": null, "status": "draft", "id": "42727c37-29c7-534f-b0f7-900992c16def"}, {"name": "冯玉", "aliases": ["馮玉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯皇后的兄长，后晋官员。《资治通鉴》记其由礼部郎中、盐铁判官被迅速擢为端明殿学士、户部侍郎；《旧五代史》另记知制诰、中书舍人、颍州团练使等任职。各书路径分别保留，生卒年本批未核。", "biography": null, "status": "draft", "id": "b4626ebf-1219-5b9b-baca-73e491e175f8"}, {"name": "李彦韬（后晋宣徽使）", "aliases": ["李彥韜（後晉宣徽使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，早年曾侍奉阎宝，后来入石敬瑭帐下并留在太原侍奉石重贵。945年任宣徽北院使、暂代侍卫马步都虞候，与冯玉争桑维翰的权力。与早期曾名李彦韬的温韬分档，温韬在后唐明宗时已被赐死。生卒年本段未载。", "biography": null, "status": "draft", "id": "e4ac4a2d-843f-5686-98da-4b16e23f906d"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "薛超", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋亲军将。946年十二月癸酉，石重贵准备与后宫人员投火自尽时，他将皇帝拦住。生卒年、籍贯未载。", "biography": null, "status": "draft", "id": "35a4e56e-b5d8-58d2-b411-af3f6cf2c20f"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}, {"name": "石延煦", "aliases": ["延煦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的孙子，石重贵养子，石延宝的兄长。946年任镇宁节度使，与赵在礼的女儿成婚；《资治通鉴》记三月庚申，《旧五代史》记四月，婚事纪月不同，分别保留。亲生父母姓名及生卒年未载。", "biography": null, "status": "draft", "id": "ed348273-f4e9-5b33-9080-aa449de66dcc"}, {"name": "石延宝", "aliases": ["石延寶", "延宝", "延寶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的孙子，石重贵养子，石延煦的弟弟。946年记石延煦婚事时，史书补叙二人为石重贵养子。亲生父母姓名与收养年月、生卒年未载。", "biography": null, "status": "draft", "id": "79b31372-7a96-5605-a27f-799f2f8a9daf"}, {"name": "傅住儿", "aliases": ["傅住兒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹通事。946年十二月耶律德光派张彦泽领二千骑先取大梁，让傅住儿任都监。姓名展示用简体儿，原文傅住兒保留；生卒年本批未核。", "biography": null, "status": "draft", "id": "12d197f3-4308-5bdc-8f6b-0f011bde8459"}, {"name": "孟承诲", "aliases": ["孟承誨"], "era": "五代十国", "birth_year": null, "death_year": 946, "description": "后晋宣徽使。946年十二月张彦泽入京后，石重贵召他商议，他躲藏未到，随后被张彦泽捕杀。《资治通鉴》还称他此前凭巧言得宠，属于史家评价；出生年未载。", "biography": null, "status": "draft", "id": "4ebec0ca-cbde-575a-b88e-d7959e2f2e75"}, {"name": "高勋", "aliases": ["高勛"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋阁门使。946年十二月丙寅，杜重威派他向契丹送降表，耶律德光赐诏接受。与军将关勋分别识别；生卒年本批未核。", "biography": null, "status": "draft", "id": "ea4f636d-1bb8-5b40-a94d-0da7caf7ebea"}, {"name": "李涛（后晋宋初官员）", "aliases": ["李濤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李澣的兄长，后晋至宋初官员。《宋史》记他宋初任兵部尚书，去世时六十四岁，年代与887年已在杨行密军中的同名李涛不相容，本批单独建档。生卒年不凭年龄反推，后续旧库记录需逐条核对。", "biography": null, "status": "draft", "id": "c03574d2-e4e9-5739-be38-c52f0c0de233"}, {"name": "冯氏（石重贵后）", "aliases": ["吴国夫人冯氏", "馮氏（石重贵后）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯濛的女儿、冯玉的妹妹。先嫁石重胤，夫死后守寡；石敬瑭去世后被石重贵纳入宫中，943年十月戊申由吴国夫人立为皇后，随后参与政务。具体个人名字与生卒年未载。", "biography": null, "status": "draft", "id": "a9036cf2-4b6b-5883-a952-511979eb35f7"}, {"name": "李筠（后晋控鹤指挥使）", "aliases": ["李筠（後晉控鶴指揮使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋控鹤指挥使。946年十二月甲戌，张彦泽派他率兵看守被迁到开封府的石重贵，内外联系断绝。与晚唐897年被杀的捧日都头李筠不是同一人，分别建档；生卒年本批未核。", "biography": null, "status": "draft", "id": "fc58c65d-118e-50cc-b682-be4eb87937e4"}, {"name": "乌氏公主", "aliases": ["烏氏公主"], "era": "五代十国", "birth_year": null, "death_year": 946, "description": "石重贵的姑母。946年十二月甲戌，贿赂守门人进入开封府，与被拘的石重贵告别，回到宅第后自缢。原文称乌氏公主，个人名字、出生年及婚配尚未核。", "biography": null, "status": "draft", "id": "553c3f7c-5531-5ee8-8ba4-25561fac8414"}, {"name": "丁氏（楚国夫人）", "aliases": ["丁氏（楚國夫人）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国夫人，石延煦的母亲。946年十二月条下记张彦泽强行把她带走。原文未给个人名字、婚配或生卒年；母亲身份按本段明确记载。", "biography": null, "status": "draft", "id": "31641d91-c801-54a6-8f38-9882256ce895"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "史书记皇甫遇起初没有参与杜重威的投降谋议", "start_year": 946, "end_year": 946, "time_original": "946年十二月杜重威投降之时", "dynasty": "五代十国", "description": "史书记皇甫遇起初没有参与杜重威的投降谋议。", "phases": [], "location_name": "晋军行营", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7ad459e8-d320-58cb-9c61-6239c3a29c3b"}, {"title": "皇甫遇拒绝耶律德光让他率兵先取大梁的安排，并向亲近人表达不愿再攻旧主", "start_year": 946, "end_year": 946, "time_original": "946年十二月晋军降后", "dynasty": "五代十国", "description": "皇甫遇拒绝耶律德光让他率兵先取大梁的安排，并向亲近人表达不愿再攻旧主。", "phases": [], "location_name": "契丹军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1db67efb-cf3f-543b-88d2-3904f68bdc41"}, {"title": "皇甫遇到平棘，称数日未食、不愿南行，随后自杀", "start_year": 946, "end_year": 946, "time_original": "946年十二月晋军降后，具体日未载", "dynasty": "五代十国", "description": "皇甫遇到平棘，称数日未食、不愿南行，随后自杀。", "phases": [], "location_name": "平棘", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "658078f9-7efa-5e3b-a162-4aaed8033f34"}, {"title": "张彦泽疾行，夜渡白马津", "start_year": 946, "end_year": 946, "time_original": "946年十二月进入大梁前，具体夜未载", "dynasty": "五代十国", "description": "张彦泽疾行，夜渡白马津。", "phases": [], "location_name": "白马津", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "18bc7001-e09f-52ed-a30f-fc86d3c32fbd"}, {"title": "石重贵收到杜重威等投降的消息", "start_year": 946, "end_year": 946, "time